'use strict';
const Core=window.DanuriCore;
const Analytics=window.DanuriAnalytics;
const track=(event,params)=>Analytics?.track(event,params);
const writingTracked=new Set();
const DATA=window.TOPIK_DATA||{items:[],questions:[],sources:[],writing:[]};
const STORAGE_KEY='danuri-topik-state-v1';
const app=document.querySelector('#app');
const icons={home:'⌂',library:'▤',collection:'♡',exams:'✎',stats:'▥',settings:'⚙'};
const labels={home:'Today',library:'Explore',collection:'My collection',exams:'Mock tests',stats:'Progress',settings:'Settings'};
const kindNames={vocabulary:'Vocabulary',expression:'Expressions',grammar:'Grammar'};
let storageWarning='',state=loadState(),view='home',kind='all',query='',libraryLevel=state.level,limit=18,collectionFilter='all',modal=null,toastTimer=null,deferredPrompt=null,result=null,writingId=DATA.writing[0]?.id||'',showModel=false;
let toastMessage='';
let suspendedQuiz=null;
const customId=()=> 'custom-'+(globalThis.crypto?.randomUUID?.() || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2,12)}`);
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml;
const allItems=()=>[...DATA.items,...state.custom];
const itemById=id=>allItems().find(x=>x.id===id);
const examName=level=>level<=2?'TOPIK I':'TOPIK II';
const levelName=level=>level<=0?'Ungraded':`${examName(level)} · Level ${level}`;
const levelBadge=level=>level>0?`${level}급`:'Ungraded';
const dueItems=()=>allItems().filter(x=>state.progress[x.id]&&state.progress[x.id].nextDue<=Date.now());
function loadState(){
  try{const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(!raw)return Core.defaultState();const s=Core.validateBackup(raw,DATA.items.map(x=>x.id));
    return s;
  }catch(err){storageWarning='Saved data could not be read. Your original storage is untouched; import a backup in Settings.';return Core.defaultState();}
}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify({...state,activeQuiz:state.activeQuiz||suspendedQuiz}));storageWarning='';}catch(err){storageWarning='Device storage is unavailable or full. Export a backup in Settings to keep this session.';document.querySelector('#storage-warning')?.replaceChildren(document.createTextNode(storageWarning));}}
function toast(message){toastMessage=message;let el=document.querySelector('#toast');if(el){el.textContent=message;el.classList.add('visible');}clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toastMessage='';document.querySelector('#toast')?.classList.remove('visible');},3500);}
function navButton(key,mobile=false){return `<button class="nav-item ${view===key&&!state.activeQuiz?'active':''}" data-nav="${key}" ${view===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icons[key]}</span><span>${mobile&&key==='collection'?'Saved':mobile&&key==='exams'?'Tests':labels[key]}</span>${key==='collection'&&!mobile?`<b>${state.saved.length}</b>`:''}</button>`;}
function mascot(cls=''){return `<img class="bomi ${cls}" src="assets/bomi.svg" alt="Bomi, a friendly Korean tiger wearing a hanbok and traditional hat"/>`;}
function analyticsBanner(){const status=Analytics?.status();return status?.configured&&status.choice==='unset'?`<section class="analytics-banner" aria-label="Optional analytics"><div><strong>Help Danuri grow?</strong><p>Allow Google Analytics to measure page visits and learning feature use. We do not send your name, personal cards, notes or writing.</p></div><div class="consent-actions"><button class="button outline" data-analytics-consent="denied">No thanks</button><button class="button primary" data-analytics-consent="granted">Allow analytics</button></div></section>`:'';}
function analyticsSettings(){const status=Analytics?.status();return `<div class="analytics-settings"><h3>Optional usage analytics</h3><p>${!status?.configured?'Usage analytics is currently inactive.':status.choice==='granted'?'You have allowed Google Analytics.':'Usage analytics is off until you allow it.'} Google may process browser, device and approximate-location information when enabled. Advertising features are disabled.</p><p>Your name, cards, search text, notes and writing are excluded from our event parameters. You can change your choice at any time.</p>${status?.configured?`<div class="consent-actions"><button class="button outline" data-analytics-consent="denied" ${status.choice==='denied'?'disabled':''}>Turn analytics off</button><button class="button outline" data-analytics-consent="granted" ${status.choice==='granted'?'disabled':''}>Allow analytics</button></div>`:''}</div>`;}
function render(){
  const isQuiz=!!state.activeQuiz;
  app.innerHTML=`<aside class="sidebar"><a href="#home" data-nav="home" class="brand" aria-label="Danuri home"><span class="brand-mark">ㅎ</span><span>danuri<span class="brand-sub">다누리 · Korean, together.</span></span></a><div class="nav-label">YOUR LEARNING SPACE</div><nav aria-label="Main navigation">${['home','library','collection','exams','stats'].map(k=>navButton(k)).join('')}</nav><div class="sidebar-bottom"><div class="bomi-note">${mascot()}<strong>조금씩, 매일.</strong><p>A little, every day.<br/>You’re doing great!</p></div>${navButton('settings')}<p class="local-caption"><span class="status-dot"></span> Saved on this device</p></div></aside>
  <div class="workspace"><header class="topbar"><a href="#home" data-nav="home" class="mobile-brand"><span class="brand-mark">ㅎ</span> danuri</a><div class="breadcrumb">MY KOREAN JOURNEY <span>/</span> <strong>${isQuiz?'Practice session':labels[view]}</strong></div><div class="topbar-right"><span class="local-pill"><span class="status-dot"></span><span id="network-label">${navigator.onLine?'Ready to learn':'Offline mode'}</span></span><button class="profile-button" data-nav="settings" aria-label="Profile and settings">${e(state.name.slice(0,1).toUpperCase())}</button></div></header>
  <div id="storage-warning" role="alert" class="storage-warning">${e(storageWarning)}</div><main id="main-content" class="content" tabindex="-1">${suspendedQuiz&&!isQuiz?`<div class="session-banner"><span>You have a saved ${suspendedQuiz.type==='exam'?'mini mock (timer running)':'quest'} in progress.</span><button class="text-button" data-resume>Resume →</button></div>`:''}${isQuiz?renderQuiz():result?renderResult():({home:renderHome,library:renderLibrary,collection:renderCollection,exams:renderExams,stats:renderStats,settings:renderSettings}[view]||renderHome)()}</main><footer class="page-footer"><span>Made for your next 안녕하세요.</span><span>다누리 · One small step at a time.</span></footer></div>
  ${!isQuiz?`<nav class="mobile-nav" aria-label="Mobile navigation">${['home','library','collection','exams','stats'].map(k=>navButton(k,true)).join('')}</nav>`:''}<div id="toast" class="toast ${toastMessage?'visible':''}" role="status">${e(toastMessage)}</div>${modal?renderModal():''}${analyticsBanner()}`;
  if(modal){const dlg=document.querySelector('#dialog');dlg.showModal();dlg.addEventListener('click',ev=>{if(ev.target===dlg){modal=null;render();}});dlg.addEventListener('cancel',ev=>{ev.preventDefault();modal=null;render();});setTimeout(()=>dlg.querySelector('input,textarea,button')?.focus(),0);}
  updateTimer();
  Analytics?.page(state.activeQuiz?'quiz':result?'result':view);
}
function pageHead(kicker,title,description,extra=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="page-description">${description}</p></div>${extra}</div>`;}
function levelPicker(){return `<div class="level-picker"><span>Your learning level</span><div role="group" aria-label="TOPIK learning level">${[1,2,3,4,5,6].map(l=>`<button data-level="${l}" class="${state.level===l?'selected':''}" aria-pressed="${state.level===l}"><small>${l<3?'I':'II'}</small>${l}급</button>`).join('')}</div><span class="level-end">${state.level<=2?'Beginner':state.level<=4?'Intermediate':'Advanced'}</span></div>`;}
function streak(){const days=new Set(state.sessions.map(s=>s.date));const d=new Date();if(!days.has(Core.dateKey(d)))d.setDate(d.getDate()-1);let n=0;while(days.has(Core.dateKey(d))){n++;d.setDate(d.getDate()-1);}return n;}
function renderHome(){
  const today=state.sessions.filter(s=>s.date===Core.dateKey()).reduce((n,s)=>n+s.total,0);
  const current=DATA.items.filter(i=>i.level===state.level);
  const featured=current[new Date().getDate()%Math.max(1,current.length)];
  return `${pageHead('안녕하세요, '+e(state.name).toUpperCase(),'A little Korean, every day.','Build your words. Find your voice. Make yourself at home.',`<div class="date-stamp">${new Date().toLocaleDateString('en-US',{month:'short',day:'2-digit'})}<span>오늘도 화이팅!</span></div>`)}
  ${levelPicker()}<section class="hero"><div class="hero-copy"><span class="hero-label"><span class="tiny-spark">✦</span> YOUR DAILY LITTLE QUEST</span><h2>Small steps.<br/><span>Big 안녕 energy.</span></h2><p>${levelName(state.level)} · A fresh set of words,<br class="desktop-only"/> expressions and grammar, just for you.</p><button class="button warm" data-start="learn">Let’s learn ${state.goal} <span aria-hidden="true">↗</span></button><div class="hero-progress"><span>${Math.min(today,state.goal)} / ${state.goal} practiced today</span><div class="progress-track"><i style="width:${Math.min(100,today/state.goal*100)}%"></i></div></div></div><div class="hero-art"><span class="hangul-deco d1">안</span><span class="hangul-deco d2">녕</span><span class="art-star s1">✧</span><span class="art-star s2">✦</span><div class="speech-bubble">같이 공부해요!<small>Let’s study together!</small></div>${mascot()}<span class="mascot-name">YOUR STUDY BUDDY, 보미</span></div></section>
  <div class="quick-stats"><div><span class="stat-icon peach">✦</span><div><strong>${streak()} <small>day${streak()===1?'':'s'}</small></strong><span>Learning streak</span></div></div><div><span class="stat-icon mint">✓</span><div><strong>${Object.values(state.progress).filter(p=>p.lastCorrect).length}<small> cards</small></strong><span>Last answered correctly</span></div></div><div><span class="stat-icon lilac">♡</span><div><strong>${state.saved.length}<small> saved</small></strong><span>Your own collection</span></div></div></div>
  <div class="section-title"><h2>Find your next little win</h2><button class="text-button" data-nav="library">Explore all <span>↗</span></button></div><div class="path-grid">${[['vocabulary','가','Words that open doors','Everyday Korean, one word at a time.','peach'],['expression','안녕','Say it like you mean it','Useful phrases for real conversations.','mint'],['grammar','은/는','Make the pieces fit','Patterns that turn words into ideas.','lilac']].map(([k,mark,title,copy,tone])=>`<button class="path-card ${tone}" data-kind-nav="${k}"><span class="path-top"><span class="path-mark">${mark}</span><span>↗</span></span><span class="eyebrow">${kindNames[k]}</span><strong>${title}</strong><span class="path-copy">${copy}</span><span class="path-count">${DATA.items.filter(i=>i.kind===k).length.toLocaleString()} learning cards</span></button>`).join('')}</div>
  <div class="lower-grid"><section class="panel word-day"><div class="section-title"><span class="eyebrow">오늘의 한 마디 · A LITTLE KOREAN</span><span class="mini-tag">${featured?.level||1}급</span></div>${featured?`<div class="featured-korean">${e(featured.korean)}<button class="sound-button" data-speak-id="${e(featured.id)}" aria-label="Listen to ${e(featured.korean)}">${soundIcon()}</button></div><p class="featured-meaning">${e(featured.english)}</p><p class="korean-example">${e(featured.example)}</p><p class="muted small">${e(featured.translation)}</p><button class="text-button" data-detail="${e(featured.id)}">Meet this ${featured.kind==='vocabulary'?'word':'pattern'} ↗</button>`:''}</section><section class="panel exam-teaser"><span class="eyebrow">READY FOR YOUR NEXT CHAPTER?</span><h2>Make friends<br/>with TOPIK.</h2><p>Listening, reading & a little courage.<br/>Try an original, timed mini mock.</p><button class="button outline" data-nav="exams">Practice a mock test ↗</button><span class="exam-doodle" aria-hidden="true">가<br/>나 다</span></section></div>
  <section class="review-strip"><span class="review-flower">✿</span><div><strong>${dueItems().length?'A familiar face, a stronger memory.':'Your review garden starts here.'}</strong><p>${dueItems().length?`${dueItems().length} cards are ready for another visit.`:'Practice a few cards and we’ll bring them back when it’s time.'}</p></div><button class="text-button" data-start="review" ${!dueItems().length?'disabled':''}>Review now →</button></section>`;
}
function soundIcon(){return '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path d="M4 9h4l5-4v14l-5-4H4zM17 8q5 4 0 8m3-11q8 7 0 14" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function filterToolbar(isCollection=false){return `<div class="filter-toolbar"><label class="search-field"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Search Korean, English or a topic…" value="${e(query)}" aria-label="Search learning cards" autocomplete="off"/></label><label class="select-label"><span class="sr-only">Filter by level</span><select id="library-level"><option value="0" ${libraryLevel===0?'selected':''}>All levels</option><option value="-1" ${libraryLevel===-1?'selected':''}>Ungraded</option>${[1,2,3,4,5,6].map(l=>`<option value="${l}" ${libraryLevel===l?'selected':''}>${levelName(l)}</option>`).join('')}</select></label></div><div class="filter-tabs" role="group" aria-label="Card type">${[['all','All cards'],...Object.entries(kindNames)].map(([k,n])=>`<button data-kind="${k}" class="${kind===k?'active':''}" aria-pressed="${kind===k}">${n}</button>`).join('')}</div>${isCollection?`<div class="collection-tabs">${[['all','All saved'],['due','Due for review'],['custom','My own cards']].map(([k,n])=>`<button data-collection-filter="${k}" class="${collectionFilter===k?'active':''}">${n}</button>`).join('')}</div>`:''}`;}
function filteredItems(collection=false){let a=allItems();if(collection)a=a.filter(i=>collectionFilter==='custom'?i.id.startsWith('custom-'):collectionFilter==='due'?state.progress[i.id]&&state.progress[i.id].nextDue<=Date.now():state.saved.includes(i.id));const q=query.toLowerCase().normalize('NFC').trim();return a.filter(i=>(!libraryLevel||(libraryLevel===-1?i.level===0:i.level===libraryLevel))&&(kind==='all'||i.kind===kind)&&(!q||[i.korean,i.english,i.definition,i.topic,i.example].some(v=>String(v||'').toLowerCase().normalize('NFC').includes(q))));}
function card(item){const saved=state.saved.includes(item.id);return `<article class="learning-card"><div class="card-meta"><span class="type-tag ${item.kind}">${kindNames[item.kind]}</span><span class="small muted">${levelBadge(item.level)}</span><button class="save-button ${saved?'saved':''}" data-save="${e(item.id)}" aria-label="${saved?'Unsave':'Save'} ${e(item.korean)}" aria-pressed="${saved}">${saved?'♥':'♡'}</button></div><button class="card-open" data-detail="${e(item.id)}"><span lang="ko" class="card-korean">${e(item.korean)}</span><span class="card-meaning">${e(item.english)}</span></button><div class="card-bottom"><span>${e(item.topic||(item.id.startsWith('custom-')?'My own card':'Original practice'))}</span><button class="sound-button" data-speak-id="${e(item.id)}" aria-label="Listen to ${e(item.korean)}">${soundIcon()}</button></div></article>`;}
function cardsSection(collection=false){const items=filteredItems(collection);return `<div class="results-meta"><span>${items.length} cards ${libraryLevel?'· '+levelName(libraryLevel):'across all levels'}</span>${collection&&items.length?'<button class="text-button" data-start="collection">Practice these cards ↗</button>':''}</div><div class="cards-grid">${items.slice(0,limit).map(card).join('')}</div>${!items.length?emptyState(collection?'Make this space your own.':'No cards found.',collection?'Save cards from Explore, add your own, or change your filters.':'Try another word, type or level.','Explore cards',collection?'library':null):''}${items.length>limit?'<button class="button outline load-more" data-more>Show more cards</button>':''}`;}
function renderLibrary(){return `${pageHead('탐색 · YOUR KOREAN TOOLKIT','A world of words awaits.','Browse vocabulary, useful expressions and grammar. Save what speaks to you.')}${catalogueCoverage()}${filterToolbar()}<div id="card-results">${cardsSection()}</div>${renderSources()}`;}
function renderCollection(){return `${pageHead('내 단어장 · YOUR PERSONAL COLLECTION','Keep the Korean you love.','Your saved cards, personal discoveries and next reviews, all in one place.',`<button class="button primary" data-open="add">+ Add a card</button>`)}<div class="collection-actions"><button class="text-button" data-export="collection">↓ Export cards</button><label class="text-button file-label">↑ Import cards<input type="file" accept="application/json,.json" id="import-cards"/></label><span class="small muted">Local to this browser · Back up to move between devices</span></div>${filterToolbar(true)}<div id="card-results">${cardsSection(true)}</div>`;}
function emptyState(title,copy,button,nav){return `<div class="empty-state"><span>✿</span><h2>${title}</h2><p>${copy}</p>${nav?`<button class="button outline" data-nav="${nav}">${button}</button>`:''}</div>`;}
function renderExams(){return `${pageHead('모의시험 · A LITTLE PRACTICE, A LOT OF CONFIDENCE','Your next chapter starts here.','Get comfortable with Korean listening, reading and writing.')}<div class="content-note"><strong>Original mini mocks</strong> · These practice sets are shorter than the official exam. Results are practice percentages, not TOPIK scores or level certification.</div><div class="exam-grid">${['I','II'].map(ex=>{const qs=DATA.questions.filter(q=>q.exam===ex);return `<section class="panel exam-option"><span class="eyebrow">${ex==='I'?'BEGINNER · LEVELS 1–2':'INTERMEDIATE & ADVANCED · LEVELS 3–6'}</span><div class="exam-heading"><h2>TOPIK <span>${ex}</span></h2><span class="exam-flower">${ex==='I'?'✿':'✳'}</span></div><p>${ex==='I'?'Everyday conversations. Familiar places. Your first Korean milestones.':'Longer ideas. Different perspectives. A more confident Korean voice.'}</p><div class="exam-facts"><span>${qs.length} questions</span><span>${ex==='I'?25:35} minutes</span><span>Listening + Reading</span></div><button class="button ${ex==='I'?'primary':'dark'}" data-exam="${ex}" ${!qs.length?'disabled':''}>Start mini mock <span>↗</span></button></section>`;}).join('')}</div><div class="panel listening-note"><span>${soundIcon()}</span><div><strong>Listen before you begin.</strong><p>Listening uses your device’s Korean text-to-speech voice. <button class="text-button" data-speak="안녕하세요. 다누리와 함께 한국어를 공부해요.">Test Korean audio ↗</button> If audio isn’t available, use the transcript; this becomes reading-supported practice.</p></div></div>${renderWriting()}${renderAttemptHistory()}${renderSources()}`;}
function renderWriting(){const w=DATA.writing.find(w=>w.id===writingId);if(!w)return '';return `<section class="panel writing-panel"><div class="section-title"><div><span class="eyebrow">쓰기 · TOPIK II WRITING STUDIO</span><h2>Let your ideas find their words.</h2></div><span class="mini-tag">Self-assessed practice</span></div><label class="field-label" for="writing-prompt">Choose an original writing prompt</label><select id="writing-prompt">${DATA.writing.map(x=>`<option value="${e(x.id)}" ${x.id===writingId?'selected':''}>${e(x.prompt.slice(0,65))}…</option>`).join('')}</select><p class="writing-prompt" lang="ko">${e(w.prompt)}</p><label class="field-label" for="writing-draft">Your response in Korean</label><textarea id="writing-draft" rows="7" maxlength="15000" placeholder="여기에 써 보세요…">${e(state.drafts[w.id]||'')}</textarea><div class="writing-meta"><span id="writing-count">${(state.drafts[w.id]||'').length} characters · spaces included</span><span id="draft-status">Saved on this device</span></div><button class="button outline" data-toggle-model>${showModel?'Hide':'Show'} model & self-check</button>${showModel?`<div class="model-answer"><h3>One possible response</h3><p lang="ko">${e(w.modelAnswer)}</p><h3>Reflect on your writing</h3>${w.rubric.map(r=>`<label class="check-label"><input type="checkbox"/>${e(r)}</label>`).join('')}<p class="small muted">No automatic writing score. Compare your response and ask a teacher for feedback.</p></div>`:''}</section>`;}
function renderAttemptHistory(){return !state.attempts.length?'':`<section class="panel"><h2>Your mock journal</h2><div class="history-list">${state.attempts.slice(-8).reverse().map(a=>`<div><span>TOPIK ${a.exam} mini mock<small>${new Date(a.finishedAt).toLocaleDateString()}</small></span><strong>${a.correct}/${a.total} <span class="muted">${Math.round(a.correct/a.total*100)}%</span></strong></div>`).join('')}</div></section>`;}
function catalogueCoverage(){const c=DATA.catalogueSummary;if(!c)return '';return `<section class="content-note catalogue-coverage"><strong>${c.vocabulary.toLocaleString()} sourced words · ${c.expressionHeadwords.toLocaleString()} expressions · ${c.grammarHeadwords.toLocaleString()} grammar patterns</strong><p>Vocabulary by learning level: ${Object.entries(c.vocabularyByLevel).map(([l,n])=>`L${l}: ${n.toLocaleString()}`).join(' · ')}.</p><p>NIKL curriculum and dictionary materials. These are learning levels, not official TOPIK word assignments. Ungraded patterns are available under All levels or Ungraded. Past-exam occurrence has not been verified.</p></section>`;}
function renderSources(){return `<section class="sources"><h3>Sources you can check</h3><p>Vocabulary uses NIKL curriculum levels and Korean Basic Dictionary glosses and sentence examples. Dictionary-only beginner words are mapped to app Level 1. Expressions and grammar without an exact curriculum match remain Ungraded. Multiple dictionary senses share one headword card.</p><div>${DATA.sources.map(s=>`<a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a>`).join('')}</div><p>Dictionary-derived text: CC BY-SA 2.0 KR. Curriculum list: KOGL Type 1. Danuri normalized, matched and grouped source entries.</p><div><a href="data/ATTRIBUTION.md" target="_blank" rel="noopener">Attribution & licenses ↗</a><a href="data/nikl-catalogue.json" download>Download attributed learning data ↓</a></div><p class="small">The 40 mini mock questions and writing tasks are original practice, not official past papers. No verified past-exam occurrence is claimed for the catalogue. This independent app is not affiliated with TOPIK, NIIED or NIKL.</p></section>`;}
function itemProvenance(i){if(!i.dictionaryEntry)return `<p class="small muted">${i.id.startsWith('custom-')?'Personal card':'Project-authored supplementary card · Suggested learning level '+i.level}</p>`;return `<div class="item-provenance"><strong>NIKL source material</strong><p>${i.levelBasis==='curriculum'?'Learning level from the NIKL curriculum; not an official TOPIK assignment.':i.levelBasis==='dictionary-beginner'?'NIKL beginner vocabulary mapped to app Level 1; not an official TOPIK assignment.':'Ungraded dictionary entry; no TOPIK level is assigned.'}</p><p>Past-exam occurrence: not verified.</p><a target="_blank" rel="noopener noreferrer" href="https://krdict.korean.go.kr/eng/dicSearch/SearchView?nation=eng&ParaWordNo=${encodeURIComponent(i.dictionaryEntry)}">Read dictionary entry ${e(i.dictionaryEntry)} ↗</a><p class="small">NIKL Korean Basic Dictionary · CC BY-SA 2.0 KR. ${i.sourceEntry?'Curriculum/source row: '+e(i.sourceEntry):''} <a href="data/ATTRIBUTION.md" target="_blank" rel="noopener">Attribution</a></p></div>`;}

function safeUrl(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?e(u.href):'#';}catch{return '#';}}
function renderStats(){const total=state.sessions.reduce((n,s)=>n+s.total,0),correct=state.sessions.reduce((n,s)=>n+s.correct,0);const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {date:Core.dateKey(d),name:d.toLocaleDateString('en',{weekday:'short'}),value:state.sessions.filter(s=>s.date===Core.dateKey(d)).reduce((n,s)=>n+s.total,0)};});const max=Math.max(state.goal,...days.map(d=>d.value));return `${pageHead('학습 기록 · EVERY STEP COUNTS','Look how far you’re going.','Real practice, small victories. Your journey grows one day at a time.')}<div class="metric-grid">${[[total,'Questions practiced'],[total?Math.round(correct/total*100)+'%':'—','Practice accuracy'],[streak(),'Day learning streak'],[dueItems().length,'Cards due for review']].map(([n,t])=>`<div class="panel"><strong>${n}</strong><span>${t}</span></div>`).join('')}</div><div class="lower-grid"><section class="panel"><h2>A week of little steps</h2><div class="bar-chart" role="img" aria-label="Practice over the last seven days: ${days.map(d=>`${d.name} ${d.value}`).join(', ')}">${days.map(d=>`<div><span>${d.value}</span><div class="bar-slot"><i style="height:${d.value/max*100}%"></i></div><small>${d.name}</small></div>`).join('')}</div></section><section class="panel"><h2>Your growing toolkit</h2><div class="kind-progress">${Core.kinds.map(k=>{const items=allItems().filter(i=>i.kind===k),n=items.filter(i=>state.progress[i.id]).length;return `<div><span>${kindNames[k]} <strong>${n} / ${items.length}</strong></span><div class="progress-track"><i style="width:${items.length?n/items.length*100:0}%"></i></div></div>`;}).join('')}</div><button class="button outline" data-start="review" ${!dueItems().length?'disabled':''}>Revisit due cards →</button></section></div>${renderAttemptHistory()}${!state.sessions.length?emptyState('Your first step is waiting.','Finish a daily quest or a mini mock to start your journal.','Start learning','home'):''}`;}
function renderSettings(){return `${pageHead('설정 · YOUR SPACE, YOUR PACE','Make yourself at home.','Set your rhythm, keep a backup, and take Korean with you.')}<div class="settings-grid"><form id="profile-form" class="panel"><h2>Your learning rhythm</h2><label class="field-label" for="learner-name">What should Bomi call you?</label><input id="learner-name" name="name" maxlength="40" value="${e(state.name)}" required/><label class="field-label" for="goal">Daily question goal</label><select id="goal" name="goal">${[5,10,20].map(n=>`<option ${n===state.goal?'selected':''} value="${n}">${n} questions a day</option>`).join('')}</select><button class="button primary" type="submit">Save preferences</button><p class="small muted">Choose your TOPIK level on Today. No account is required.</p></form><section class="panel"><h2>Your Korean, to go.</h2><p>Install Danuri on your home screen for an app-like experience. Core cards and practice are cached after your first online visit.</p><button class="button outline" data-install>Install / home screen guide ↗</button><p class="small muted">Android: browser menu → Install app.<br/>iPhone: Safari → Share → Add to Home Screen.<br/>Offline voice depends on your device’s installed Korean voice.</p></section><section class="panel"><h2>Keep your little discoveries.</h2><p>Cards, notes, progress, mock history and writing drafts are saved in this browser. Other devices have separate storage.</p><button class="button primary" data-export="backup">↓ Download full backup</button><label class="button outline file-label">↑ Restore full backup<input type="file" accept="application/json,.json" id="import-backup"/></label><p class="small muted">Restore replaces local data after confirmation. Export a backup before switching browsers or clearing site data. There is no cloud sync.</p></section><section class="panel"><h2>A space you can trust.</h2><p>No login or server account. Learning records stay on this device. Optional usage analytics helps improve Danuri only if you allow it.</p><p class="small muted">Voice playback uses your browser or operating system speech service; availability and processing depend on your device.</p>${analyticsSettings()}<button class="text-button danger" data-open="reset">Reset this device’s data</button></section></div>${renderSources()}`;}
function renderQuiz(){const quiz=state.activeQuiz,q=quiz.questions[quiz.index],selected=quiz.answers[quiz.index],answered=Number.isInteger(selected),exam=quiz.type==='exam';return `<div class="quiz-top"><button class="text-button" data-open="exit">← ${exam?'Save & leave':'Leave practice'}</button><span class="mini-tag">${exam?'TOPIK '+quiz.exam+' · Mini mock':'Your '+(quiz.type==='review'?'review':'daily')+' quest'}</span>${exam?'<span class="timer" id="quiz-timer" role="timer"></span>':`<span class="muted small">${quiz.index+1} / ${quiz.questions.length}</span>`}</div><div class="progress-track quiz-progress"><i style="width:${Object.keys(quiz.answers).length/quiz.questions.length*100}%"></i></div><section class="quiz-card panel"><div class="section-title"><span class="eyebrow">QUESTION ${quiz.index+1} OF ${quiz.questions.length}</span><span class="type-tag">${e(q.section)}</span></div><h1 class="question-prompt" lang="ko">${e(q.prompt)}</h1>${q.audio?`<div class="audio-panel"><button class="button outline" data-speak="${e(q.audio)}">${soundIcon()} Play Korean audio</button><details><summary>Show transcript (reading support)</summary><p lang="ko">${e(q.audio)}</p></details></div>`:''}${q.passage?`<div class="question-passage" lang="ko">${e(q.passage)}</div>`:''}<div class="answer-options">${q.options.map((o,i)=>`<button class="answer-option ${selected===i?'chosen':''} ${!exam&&answered&&i===q.answer?'correct':''} ${!exam&&answered&&selected===i&&i!==q.answer?'incorrect':''}" data-answer="${i}" aria-pressed="${selected===i}" ${!exam&&answered?'disabled':''}><span>${i+1}</span><span>${e(o)}</span>${selected===i?'<b>✓</b>':''}</button>`).join('')}</div>${!exam&&answered?`<div class="feedback ${selected===q.answer?'good':'gentle'}"><strong>${selected===q.answer?'잘했어요! Nicely done.':'괜찮아요. Let’s meet this one again.'}</strong><p>${e(q.explanation)}</p></div>`:''}<div class="quiz-actions"><button class="button outline" data-quiz-prev ${!exam||quiz.index===0?'disabled':''}>← Previous</button>${quiz.index===quiz.questions.length-1?`<button class="button primary" data-submit ${!exam&&!answered?'disabled':''}>${exam?'Submit mini mock':'Finish quest'} ✓</button>`:`<button class="button primary" data-quiz-next ${!exam&&!answered?'disabled':''}>${exam?'Next question':'Continue'} →</button>`}</div></section>${exam?`<div class="question-nav" aria-label="Question navigation">${quiz.questions.map((q,i)=>`<button data-question-index="${i}" class="${i===quiz.index?'current':''} ${Number.isInteger(quiz.answers[i])?'answered':''}" aria-label="Question ${i+1}${Number.isInteger(quiz.answers[i])?', answered':''}" ${i===quiz.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p class="small muted centered">Answers stay hidden until submission. Your timer continues if you leave or reload.</p>`:`<p class="small muted centered">${mascot('tiny-bomi')} Bomi says: One small step is still a step.</p>`}`;}
function renderResult(){const r=result,grade=r.grade;return `<section class="result-hero panel">${mascot()}<span class="eyebrow">수고했어요 · YOU SHOWED UP</span><h1>${grade.percent>=80?'Look at you grow!':'A little wiser than before.'}</h1><div class="result-score">${grade.correct}<span>/ ${grade.total}</span></div><p>${grade.percent}% correct · ${r.type==='exam'?'Mini mock practice result, not an official TOPIK score.':'Every revisit makes a stronger memory.'}</p><div class="result-breakdown">${[...new Set(grade.rows.map(r=>r.question.section))].map(s=>{const rows=grade.rows.filter(r=>r.question.section===s);return `<span>${e(s)} <strong>${rows.filter(r=>r.correct).length}/${rows.length}</strong></span>`;}).join('')}</div><div class="result-actions"><button class="button primary" data-finish-result>Back to ${r.type==='exam'?'mock tests':'Today'}</button>${grade.correct<grade.total?'<button class="button outline" data-practice-mistakes>Review missed cards →</button>':''}</div></section><div class="section-title"><h2>A moment to reflect</h2><span class="muted small">Answers & explanations</span></div><div class="result-rows">${grade.rows.map((row,i)=>`<details class="panel result-row" ${!row.correct?'open':''}><summary><span class="result-dot ${row.correct?'good':'bad'}">${row.correct?'✓':'↻'}</span><span>${i+1}. ${e(row.question.prompt)}</span><strong>${row.correct?'Correct':row.selected===null?'Skipped':'Revisit'}</strong></summary>${row.question.passage?`<p lang="ko">${e(row.question.passage)}</p>`:''}${row.question.audio?`<p lang="ko">${e(row.question.audio)}</p>`:''}<p>Your answer: ${row.selected===null?'Not answered':e(row.question.options[row.selected])}</p><p><strong>Correct: ${e(row.question.options[row.question.answer])}</strong></p><p class="explanation">${e(row.question.explanation)}</p>${itemById(row.question.relatedId)?`<button class="text-button" data-detail="${e(row.question.relatedId)}">Explore related card ↗</button>`:''}</details>`).join('')}</div>`;}
function renderModal(){let body='';
  if(modal.type==='detail'){const i=itemById(modal.id);if(!i)return '';const source=DATA.sources.find(s=>s.id===i.sourceId);body=`<span class="type-tag ${i.kind}">${kindNames[i.kind]} · ${levelBadge(i.level)}</span><h2 class="detail-korean" lang="ko">${e(i.korean)}</h2><p class="detail-meaning">${e(i.english)}</p>${i.definition?`<p class="dictionary-definition">${e(i.definition)}</p>`:''}${i.romanization?`<p class="muted">${e(i.romanization)}</p>`:''}<button class="button outline" data-speak-id="${e(i.id)}">${soundIcon()} Listen in Korean</button><div class="example-box"><span class="eyebrow">${i.example?'IN A SENTENCE':'DICTIONARY CONTEXT'}</span>${i.example?`<p lang="ko">${e(i.example)}</p>${i.translation?`<span>${e(i.translation)}</span>`:''}<button class="sound-button" data-speak="${e(i.example)}" aria-label="Listen to example">${soundIcon()}</button>`:'<p>This source entry has no sentence example. Read its definition and dictionary entry for usage.</p>'}</div>${i.senses?.length>1?`<details class="other-senses"><summary>${i.senses.length} dictionary meanings</summary>${i.senses.map(x=>`<p>${e(x.english)}</p>${x.example?`<p lang="ko">${e(x.example)}</p>`:''}`).join('')}</details>`:''}<label class="field-label" for="card-note">A note to your future self</label><textarea id="card-note" maxlength="4000" rows="3" placeholder="A memory, a connection, a little reminder…">${e(state.notes[i.id]||'')}</textarea><div class="detail-actions"><button class="button primary" data-save="${e(i.id)}">${state.saved.includes(i.id)?'♥ Saved · Unsave':'♡ Save to my collection'}</button><button class="button outline" data-save-note="${e(i.id)}">Save note</button></div>${itemProvenance(i)}<a class="text-button" href="https://krdict.korean.go.kr/eng/dicSearch/search?nation=eng&amp;mainSearchWord=${encodeURIComponent(i.korean)}" target="_blank" rel="noopener noreferrer">Look up in NIKL dictionary ↗</a>${i.sourceUrl?`<p><a href="${safeUrl(i.sourceUrl)}" target="_blank" rel="noopener noreferrer">My source ↗</a></p>`:''}${i.id.startsWith('custom-')?`<p><button class="text-button danger" data-delete-card="${e(i.id)}">Delete personal card</button></p>`:''}`;}
  if(modal.type==='add')body=`<span class="eyebrow">나만의 카드 · A NEW DISCOVERY</span><h2>A little Korean to keep.</h2><form id="add-card-form"><div class="form-pair"><label>Card type<select name="kind">${Object.entries(kindNames).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></label><label>Suggested level<select name="level">${[1,2,3,4,5,6].map(l=>`<option value="${l}" ${l===state.level?'selected':''}>Level ${l}</option>`).join('')}</select></label></div><label>Korean word, expression or pattern<input name="korean" required maxlength="300" lang="ko" placeholder="예: 반갑습니다"/></label><label>English meaning / explanation<textarea name="english" required maxlength="1000" rows="2" placeholder="Nice to meet you (formal)."></textarea></label><label>Korean example<input name="example" maxlength="4000" lang="ko"/></label><label>English translation<input name="translation" maxlength="4000"/></label><label>Topic<input name="topic" maxlength="100" placeholder="Introductions, food, work…"/></label><label>Source URL (optional)<input name="sourceUrl" type="url" placeholder="https://…"/></label><button class="button primary" type="submit">Add to my collection +</button><p id="form-error" role="alert" class="error"></p></form>`;
  if(modal.type==='exit')body=`<h2>${state.activeQuiz.type==='exam'?'Keep your place?':'Leave this quest?'}</h2><p>${state.activeQuiz.type==='exam'?'Your answers are saved. The timer keeps running and the exam will be submitted when time runs out.':'Your in-progress answers will be saved. Finish the quest to add it to your journal.'}</p><button class="button primary" data-leave-quiz>Save & leave</button><button class="button outline" data-close>Keep practicing</button>`;
  if(modal.type==='submit')body=`<h2>Ready to finish?</h2><p>${state.activeQuiz.questions.length-Object.keys(state.activeQuiz.answers).length} unanswered questions. Skipped answers count as incorrect in this practice result.</p><button class="button primary" data-confirm-submit>Submit now</button><button class="button outline" data-close>Keep working</button>`;
  if(modal.type==='resume')body=`<h2>A little quest is waiting.</h2><p>There is already a saved session. Resume it, or finish it before starting this new one. Finishing records unanswered questions as incorrect. A saved mini mock’s timer keeps running.</p><button class="button primary" data-resume>Resume saved session</button><button class="button outline" data-finish-and-start>Finish saved & start new</button>`;
  if(modal.type==='restore')body=`<h2>Restore this backup?</h2><p>This replaces the learning data in this browser with ${modal.backup.custom.length} personal cards, ${modal.backup.saved.length} saved cards and ${modal.backup.sessions.length} practice sessions. Download your current backup first if you want to keep it.</p><button class="button outline" data-export="backup">Download current backup</button><button class="button primary" data-confirm-restore>Replace & restore</button>`;
  if(modal.type==='reset')body=`<h2>Start a fresh page?</h2><p>This clears personal cards, saved cards, notes, drafts and progress on this device. Built-in learning material stays available.</p><button class="button outline" data-export="backup">Download a backup first</button><button class="button danger-button" data-confirm-reset>Clear this device’s data</button>`;
  if(modal.type==='install')body=`<span class="eyebrow">KOREAN, IN YOUR POCKET</span><h2>Take Danuri with you.</h2>${mascot('install-bomi')}<p><strong>Android Chrome:</strong> menu (⋮) → Install app or Add to Home screen.</p><p><strong>iPhone Safari:</strong> Share → Add to Home Screen → Open as Web App → Add.</p><p class="small muted">Installation and offline caching require HTTPS or localhost. For a phone on your Wi-Fi, run npm run serve:lan on your computer and open its local IP on port 8091. This LAN preview supports browsing; install/offline features require HTTPS.</p>`;
  return `<dialog id="dialog" aria-label="${modal.type==='detail'?'Learning card':modal.type==='add'?'Add a learning card':'Danuri dialog'}"><button class="dialog-close" data-close aria-label="Close dialog">×</button>${body}</dialog>`;
}
function navigate(next){if(state.activeQuiz){suspendedQuiz=state.activeQuiz;state.activeQuiz=null;}result=null;modal=null;view=Object.keys(labels).includes(next)?next:'home';query='';limit=18;history.replaceState(null,'','#'+view);save();render();window.scrollTo({top:0});}
function startStudy(type,ids){if(suspendedQuiz||state.activeQuiz){modal={type:'resume',pending:{type,ids}};render();return;}let items=type==='review'?dueItems():type==='collection'?filteredItems(true):allItems().filter(i=>i.level===state.level);if(ids)items=ids.map(itemById).filter(Boolean);if(!items.length){toast('No cards match yet. Try another level or save a few cards.');return;}const questions=Core.buildStudyQuestions(items,allItems(),state.goal);state.activeQuiz={type:type==='review'?'review':'learn',questions,answers:{},index:0,startedAt:Date.now(),deadline:null};result=null;track('study_start',{session_type:state.activeQuiz.type,learning_level:state.level,question_count:questions.length});save();render();window.scrollTo({top:0});}
function startExam(exam){if(suspendedQuiz||state.activeQuiz){modal={type:'resume',pending:{type:'exam',exam}};render();return;}const questions=DATA.questions.filter(q=>q.exam===exam);if(!questions.length)return;state.activeQuiz={type:'exam',exam,questions,answers:{},index:0,startedAt:Date.now(),deadline:Date.now()+(exam==='I'?25:35)*60000};result=null;track('mock_start',{exam_type:exam,learning_level:state.level,question_count:questions.length});save();render();window.scrollTo({top:0});}
function resumeQuiz(){state.activeQuiz=state.activeQuiz||suspendedQuiz;suspendedQuiz=null;modal=null;save();render();toast('Your in-progress session is ready.');}
function finishQuiz(reason='submitted'){const q=state.activeQuiz||suspendedQuiz;if(!q)return;const grade=Core.gradeQuiz(q.questions,q.answers);track(q.type==='exam'?'mock_complete':'study_complete',{session_type:q.type,exam_type:q.exam||'',learning_level:state.level,question_count:grade.total,correct_count:grade.correct,score_percent:grade.percent,duration_seconds:Math.round((Date.now()-q.startedAt)/1000),exit_reason:reason});grade.rows.forEach(row=>Core.updateProgress(state.progress,row.question.relatedId,row.correct));state.sessions.push({date:Core.dateKey(),total:grade.total,correct:grade.correct,type:q.type});state.sessions=state.sessions.slice(-1000);if(q.type==='exam'){state.attempts.push({exam:q.exam,total:grade.total,correct:grade.correct,finishedAt:Date.now()});state.attempts=state.attempts.slice(-100);}result={grade,type:q.type,exam:q.exam};state.activeQuiz=null;suspendedQuiz=null;view=q.type==='exam'?'exams':'home';modal=null;save();render();window.scrollTo({top:0});}
function updateTimer(){const q=state.activeQuiz||suspendedQuiz;if(!q?.deadline)return;const left=Math.max(0,q.deadline-Date.now());if(!left){finishQuiz('time_limit');toast('Time is up. Your mini mock has been submitted.');return;}const el=document.querySelector('#quiz-timer');if(el){el.textContent=`${String(Math.floor(left/60000)).padStart(2,'0')}:${String(Math.floor(left/1000)%60).padStart(2,'0')}`;el.classList.toggle('urgent',left<120000);}}
function speak(text){if(!('speechSynthesis' in window)){toast('Korean audio is unavailable. Use the written example or transcript.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='ko-KR';utterance.rate=.85;const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('ko'));if(voice)utterance.voice=voice;utterance.onerror=event=>{if(!['interrupted','canceled'].includes(event.error))toast('Korean audio is unavailable on this device. Use the transcript.');};speechSynthesis.speak(utterance);}
function download(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your download is ready.');}
async function importFile(file,backup){if(!file)return;try{if(file.size>5000000)throw new Error('Choose a JSON file smaller than 5 MB.');const raw=JSON.parse(await file.text());if(backup){const checked=Core.validateBackup(raw,DATA.items.map(i=>i.id));modal={type:'restore',backup:checked};render();return;}const rows=Array.isArray(raw)?raw:raw.cards;if(!Array.isArray(rows)||!rows.length||rows.length>5000)throw new Error('Import a non-empty cards array (maximum 5,000 cards).');if(state.custom.length+rows.length>5000)throw new Error('Your collection can contain at most 5,000 personal cards.');const checked=rows.map(Core.validItem);const keys=new Set(allItems().map(i=>i.kind+'|'+i.korean+'|'+i.english));let added=0;for(const i of checked){const key=i.kind+'|'+i.korean+'|'+i.english;if(keys.has(key))continue;i.id=customId();keys.add(key);state.custom.push(i);state.saved.push(i.id);added++;}track('collection_import',{added_count:added});save();render();toast(`${added} cards added. Duplicates skipped.`);}catch(err){toast('Import failed: '+err.message);}}
app.addEventListener('click',async event=>{
  const b=event.target.closest('button,a[data-nav]');if(!b)return;
  if(b.dataset.nav){event.preventDefault();navigate(b.dataset.nav);return;}
  if(b.dataset.analyticsConsent){Analytics.setConsent(b.dataset.analyticsConsent);render();toast(b.dataset.analyticsConsent==='granted'?'Usage analytics enabled.':'Usage analytics turned off.');return;}
  if(b.hasAttribute('data-resume')){resumeQuiz();return;}
  if(b.hasAttribute('data-finish-and-start')){const pending=modal.pending;finishQuiz('replaced');pending.type==='exam'?startExam(pending.exam):startStudy(pending.type,pending.ids);return;}
  if(b.hasAttribute('data-close')){modal=null;render();return;}
  if(b.dataset.level){state.level=Number(b.dataset.level);track('select_level',{learning_level:state.level});libraryLevel=state.level;save();render();return;}
  if(b.dataset.kindNav){kind=b.dataset.kindNav;libraryLevel=kind==='vocabulary'?state.level:0;navigate('library');return;}
  if(b.hasAttribute('data-kind')){kind=b.dataset.kind;limit=18;render();return;}
  if(b.dataset.collectionFilter){collectionFilter=b.dataset.collectionFilter;limit=18;render();return;}
  if(b.dataset.save){const id=b.dataset.save;if(!itemById(id))return;const saved=state.saved.includes(id);state.saved=saved?state.saved.filter(x=>x!==id):[...state.saved,id];track(saved?'unsave_item':'save_item',Analytics.cardParams(itemById(id)));save();render();toast(saved?'Removed from your collection.':'Saved to your collection.');return;}
  if(b.dataset.detail){const item=itemById(b.dataset.detail);if(item)track('view_item',Analytics.cardParams(item));modal={type:'detail',id:b.dataset.detail};render();return;}
  if(b.dataset.speakId){const item=itemById(b.dataset.speakId);if(item)speak(item.korean);return;}
  if(b.dataset.speak){speak(b.dataset.speak);return;}
  if(b.dataset.open){modal={type:b.dataset.open};render();return;}
  if(b.hasAttribute('data-more')){limit+=18;document.querySelector('#card-results').innerHTML=cardsSection(view==='collection');return;}
  if(b.dataset.start){startStudy(b.dataset.start);return;}
  if(b.dataset.exam){startExam(b.dataset.exam);return;}
  if(b.hasAttribute('data-answer')){const q=state.activeQuiz;if(!q||q.type!=='exam'&&Number.isInteger(q.answers[q.index]))return;q.answers[q.index]=Number(b.dataset.answer);save();render();return;}
  if(b.hasAttribute('data-quiz-next')||b.hasAttribute('data-quiz-prev')){const q=state.activeQuiz;q.index=Math.max(0,Math.min(q.questions.length-1,q.index+(b.hasAttribute('data-quiz-next')?1:-1)));save();render();return;}
  if(b.hasAttribute('data-question-index')){state.activeQuiz.index=Number(b.dataset.questionIndex);save();render();return;}
  if(b.hasAttribute('data-submit')){if(state.activeQuiz.type==='exam'&&Object.keys(state.activeQuiz.answers).length<state.activeQuiz.questions.length){modal={type:'submit'};render();}else finishQuiz();return;}
  if(b.hasAttribute('data-confirm-submit')){finishQuiz();return;}
  if(b.hasAttribute('data-leave-quiz')){suspendedQuiz=state.activeQuiz;state.activeQuiz=null;modal=null;view='home';saveSuspended();render();return;}
  if(b.hasAttribute('data-finish-result')){navigate(result?.type==='exam'?'exams':'home');return;}
  if(b.hasAttribute('data-practice-mistakes')){const ids=[...new Set(result.grade.rows.filter(r=>!r.correct).map(r=>r.question.relatedId))];startStudy('review',ids);return;}
  if(b.dataset.saveNote){state.notes[b.dataset.saveNote]=document.querySelector('#card-note').value.trim();save();toast('Note saved for your future self.');return;}
  if(b.dataset.deleteCard){const id=b.dataset.deleteCard;state.custom=state.custom.filter(i=>i.id!==id);state.saved=state.saved.filter(x=>x!==id);delete state.progress[id];delete state.notes[id];modal=null;save();render();toast('Personal card deleted.');return;}
  if(b.hasAttribute('data-toggle-model')){showModel=!showModel;render();return;}
  if(b.dataset.export){const stamp=Core.dateKey();track('backup_export',{scope:b.dataset.export});download(b.dataset.export==='backup'?{...state,activeQuiz:state.activeQuiz||suspendedQuiz}:{schemaVersion:1,cards:allItems().filter(i=>state.saved.includes(i.id)||i.id.startsWith('custom-'))},`danuri-${b.dataset.export}-${stamp}.json`);return;}
  if(b.hasAttribute('data-confirm-restore')){state=modal.backup;suspendedQuiz=null;modal=null;result=null;save();render();toast('Backup restored. Welcome back.');return;}
  if(b.hasAttribute('data-confirm-reset')){state=Core.defaultState();suspendedQuiz=null;modal=null;result=null;save();render();toast('A fresh page is ready.');return;}
  if(b.hasAttribute('data-install')){if(deferredPrompt){await deferredPrompt.prompt();const decision=await deferredPrompt.userChoice;track('install_prompt',{outcome:decision.outcome});deferredPrompt=null;}else{modal={type:'install'};render();}return;}
});
function saveSuspended(){save();}
app.addEventListener('input',event=>{const t=event.target;if(t.id==='search'){query=t.value;limit=18;document.querySelector('#card-results').innerHTML=cardsSection(view==='collection');}if(t.id==='writing-draft'){if(t.value.trim()&&!writingTracked.has(writingId)){writingTracked.add(writingId);track('writing_start',{prompt_id:writingId});}state.drafts[writingId]=t.value;save();document.querySelector('#writing-count').textContent=t.value.length+' characters · spaces included';document.querySelector('#draft-status').textContent=storageWarning?'Not saved · Export a backup':'Saved on this device';}});
app.addEventListener('change',event=>{const t=event.target;if(t.id==='library-level'){libraryLevel=Number(t.value);limit=18;render();}if(t.id==='writing-prompt'){writingId=t.value;showModel=false;render();}if(t.id==='import-cards'||t.id==='import-backup'){importFile(t.files[0],t.id==='import-backup');t.value='';}});
app.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='profile-form'){const fd=new FormData(form);state.name=String(fd.get('name')).trim().slice(0,40)||'Learner';state.goal=Number(fd.get('goal'));save();render();toast('Your rhythm is set.');}if(form.id==='add-card-form'){try{if(state.custom.length>=5000)throw new Error('Personal card limit reached.');const fd=Object.fromEntries(new FormData(form));fd.level=Number(fd.level);if(!fd.sourceUrl)delete fd.sourceUrl;const i=Core.validItem(fd);if(allItems().some(x=>x.kind===i.kind&&x.korean===i.korean&&x.english===i.english))throw new Error('This card already exists. Save it from Explore instead.');i.id=customId();state.custom.push(i);state.saved.push(i.id);save();modal=null;libraryLevel=0;kind='all';query='';collectionFilter='all';render();toast('Your new discovery is saved.');}catch(err){document.querySelector('#form-error').textContent=err.message;}}});
window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(Object.keys(labels).includes(target))navigate(target);});
window.addEventListener('beforeunload',()=>saveSuspended());
window.addEventListener('online',()=>{document.querySelector('#network-label').textContent='Ready to learn';});
window.addEventListener('offline',()=>{document.querySelector('#network-label').textContent='Offline mode';});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredPrompt=event;});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateTimer();});
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(()=>toast('Offline setup is unavailable. You can keep learning online.'));
setInterval(updateTimer,1000);
view=Object.keys(labels).includes(location.hash.slice(1))?location.hash.slice(1):'home';
render();
